function dashboardTable(){const today=dateISO(new Date()),rows=dashboardRows().filter(o=>{const name=o.proveedorNombre||o._supplier?.nombre||'';return (!dashboardSearch||`${name} ${o.numero||''}`.toLocaleLowerCase('es').includes(dashboardSearch.toLocaleLowerCase('es')))&&(dashboardFilter==='todos'||dashboardFilter==='hoy'&&o._due===today||dashboardFilter==='pendientes'&&!o._paid||dashboardFilter==='pagados'&&o._paid)&&(!dashboardFrom||o._due&&o._due>=dashboardFrom)&&(!dashboardTo||o._due&&o._due<=dashboardTo)}).sort((a,b)=>(a._paid-b._paid)||(a._due||'9999').localeCompare(b._due||'9999')||(b.fecha||'').localeCompare(a.fecha||''));const count=10,pages=Math.max(1,Math.ceil(rows.length/count));dashboardPage=Math.max(1,Math.min(dashboardPage,pages));const visible=rows.slice((dashboardPage-1)*count,dashboardPage*count);const money=n=>Number(n||0).toLocaleString('es-AR',{style:'currency',currency:'ARS'});const svg=(kind)=>({search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',eye:'<path d="M2 12s3.6-6 10-6 10 6 10 6-3.6 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',edit:'<path d="m4 20 4.5-1 11-11-3.5-3.5-11 11L4 20Z"/><path d="m14.5 6.5 3.5 3.5"/>',file:'<path d="M7 2h7l5 5v15H7a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2Z"/><path d="M14 2v6h5M9 12h6M9 16h6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6M17 2v6M3 10h18"/>',heading:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 3v4h6V3M9 11h6M9 15h6"/>'})[kind];const icon=kind=>`<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${svg(kind)}</svg>`;const pageButton=(number,label,disabled=false,active=false)=>`<button type="button" data-dashboard-page="${number}" ${disabled?'disabled':''} class="${active?'active':''}" aria-label="${label}" ${active?'aria-current="page"':''}>${label}</button>`;let pagination=pageButton(1,'«',dashboardPage===1)+pageButton(dashboardPage-1,'‹',dashboardPage===1);for(let n=1;n<=pages;n++){if(pages<=7||n===1||n===pages||Math.abs(n-dashboardPage)<=1)pagination+=pageButton(n,String(n),false,n===dashboardPage);else if(n===2&&dashboardPage>3||n===pages-1&&dashboardPage<pages-2)pagination+='<span class="prov-dashboard-page-gap">…</span>'}pagination+=pageButton(dashboardPage+1,'›',dashboardPage===pages)+pageButton(pages,'»',dashboardPage===pages);return `<section class="prov-dashboard-panel"><div class="prov-dashboard-heading"><span class="prov-dashboard-heading-icon">${icon('heading')}</span><div><h2>Pedidos y vencimientos</h2><p>Control de pedidos, pagos y fechas de vencimiento.</p></div><button type="button" class="prov-primary" data-prov-action="order-new">＋ Nuevo pedido</button></div><div class="prov-dashboard-filters"><label class="prov-dashboard-search">${icon('search')}<input id="provDashboardSearch" type="search" placeholder="Buscar proveedor..." value="${esc(dashboardSearch)}" aria-label="Buscar proveedor"></label><div class="prov-dashboard-tabs" role="group" aria-label="Filtrar pedidos">${[['todos','Todos'],['hoy','Vencen hoy'],['pendientes','Pendientes'],['pagados','Pagados']].map(([v,t])=>`<button type="button" class="${dashboardFilter===v?'active':''}" data-dashboard-filter="${v}">${t}</button>`).join('')}</div><div class="prov-dashboard-dates">${icon('calendar')}<input id="provDashboardFrom" type="date" aria-label="Vencimiento desde" value="${esc(dashboardFrom)}"><span>–</span><input id="provDashboardTo" type="date" aria-label="Vencimiento hasta" value="${esc(dashboardTo)}"></div></div><div class="prov-dashboard-scroll"><table class="prov-dashboard-table"><thead><tr><th>Proveedor <span>↕</span></th><th>Valor del pedido <span>↕</span></th><th>Recibido <span>↕</span></th><th>Vencimiento <span>↕</span></th><th>Estado <span>↕</span></th><th>Acciones</th></tr></thead><tbody>${visible.length?visible.map(o=>{const name=o.proveedorNombre||o._supplier?.nombre||'Proveedor no disponible';const due=o._due;return `<tr><td><span class="prov-dashboard-avatar">${esc(name.trim().split(/\s+/).map(w=>w[0]).slice(0,2).join('').toUpperCase())}</span><strong>${esc(name)}</strong></td><td>${money(o.importe)}</td><td>${dashboardDate(o._received)}</td><td class="${due===today?'prov-dashboard-today':''}">${dashboardDate(due)}</td><td><span class="prov-dashboard-status ${o._paid?'paid':'pending'}">${o._paid?'Pagado':'Pendiente'}</span></td><td><div class="prov-dashboard-actions"><button type="button" data-dashboard-order="${esc(o.id)}" title="Ver pedido" aria-label="Ver pedido">${icon('eye')}</button><button type="button" data-dashboard-edit="${esc(o.id)}" title="Editar pedido" aria-label="Editar pedido">${icon('edit')}</button><button type="button" data-dashboard-paid="${esc(o.id)}" title="${o._paid?'Marcar pendiente':'Marcar pagado'}" aria-label="${o._paid?'Marcar pendiente':'Marcar pagado'}">${icon('file')}</button></div></td></tr>`}).join(''):`<tr><td colspan="6" class="prov-dashboard-empty">No hay pedidos para los filtros seleccionados.</td></tr>`}</tbody></table></div><div class="prov-dashboard-footer"><span>Mostrando ${rows.length?((dashboardPage-1)*count+1):0} a ${Math.min(dashboardPage*count,rows.length)} de ${rows.length} registros</span><div class="prov-dashboard-pagination">${pagination}</div></div></section>`}
function home(){const cards=['proveedores','pedidos','cronograma'];return `<div class="prov-dashboard-home">${header()}<div class="prov-dashboard-shortcuts">${cards.map(k=>{const s=sections.find(x=>x[0]===k);return `<button type="button" class="prov-dashboard-shortcut ${s[4]}" data-prov-view="${k}"><span class="prov-dashboard-shortcut-icon">${tileIcon(k)}</span><span><strong>${s[1]}</strong><small>${k==='proveedores'?'Datos comerciales y condiciones de compra de cada proveedor.':k==='pedidos'?'Registro y seguimiento de pedidos a proveedores.':'Días de pedidos y entregas de cada proveedor.'}</small></span><span class="prov-dashboard-shortcut-arrow">›</span></button>`}).join('')}</div>${dashboardTable()}${orderEdit!==null?orderForm():''}</div>`}
function sub(){let s=sections.find(x=>x[0]===view);if(!s)return home();return `${view==='cronograma'?'':`<div class="prov-subhead"><div class="prov-subtitle"><span class="prov-subtitle-icon">${view==='proveedores'?tileIcon('proveedores'):view==='pedidos'?'<svg viewBox="0 0 24 24" width="30" height="30" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="9" cy="20" r="1"/><circle cx="19" cy="20" r="1"/><path d="M2 3h3l2.5 12h12l2-9H6"/></svg>':s[3]}</span><div><h2>${s[1]}</h2><p>${s[2]}</p></div></div>${view==='proveedores'?'<button class="prov-primary" data-prov-action="new">＋ Nuevo proveedor</button>':view==='pedidos'?'<button class="prov-primary" data-prov-action="order-new">＋ Nuevo pedido</button>':''}</div>`}${view==='proveedores'?list():view==='pedidos'?orderScreen():view==='cronograma'?(window.CronogramaPedidos.render()+(orderEdit!==null?orderForm():'')):`<div class="prov-surface"><div class="prov-empty"><h3>${s[1]}</h3><p>Sección preparada para desarrollar sus herramientas y conectar los datos del sistema.</p></div></div>`}`}
function list(){const all=data();const active=all.filter(x=>(x.estado||'Activo')!=='Inactivo').length;const categories=new Set(all.map(x=>x.categoria).filter(Boolean)).size;const provinces=[...new Set(all.map(x=>x.provincia).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'es'));const rubros=[...new Set(all.map(x=>x.categoria).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'es'));const q=query.toLocaleLowerCase('es').trim();const filtered=all.filter(x=>(!q||[x.nombre,x.razon,x.cuit,x.localidad,x.provincia,x.telefono,x.email,x.categoria].join(' ').toLocaleLowerCase('es').includes(q))&&(!filterEstado||(x.estado||'Activo')===filterEstado)&&(!filterProvincia||x.provincia===filterProvincia)&&(!filterRubro||x.categoria===filterRubro));filtered.sort((a,b)=>sortDir*String(a[sortKey]||'').localeCompare(String(b[sortKey]||''),'es',{numeric:true,sensitivity:'base'}));const totalPages=Math.max(1,Math.ceil(filtered.length/pageSize));page=Math.min(page,totalPages);const visible=filtered.slice((page-1)*pageSize,page*pageSize);const stats=[['people',all.length,'Proveedores registrados','blue'],['check',active,'Proveedores activos','green'],['pause',all.length-active,'Proveedores inactivos','orange'],['box',categories,'Categorías de rubros','purple']];const options=(arr,selected,first)=>`<option value="">${first}</option>${arr.map(x=>`<option value="${esc(x)}" ${selected===x?'selected':''}>${esc(x)}</option>`).join('')}`;const heads=[['nombre','Proveedor'],['razon','Razón Social'],['cuit','CUIT'],['localidad','Localidad'],['provincia','Provincia'],['categoria','Rubro'],['telefono','Teléfono'],['email','Email'],['estado','Estado']];const icon=(name)=>name==='people'?'♟':name==='check'?'✓':name==='pause'?'Ⅱ':'⬡';return `<div class="prov-list-kpis">${stats.map(([i,n,l,c])=>`<div class="prov-list-kpi ${c}"><span class="prov-list-kpi-icon">${icon(i)}</span><span class="prov-list-kpi-copy"><strong>${n}</strong><small>${l}</small></span><span class="prov-list-kpi-arrow">›</span></div>`).join('')}</div><div class="prov-surface prov-list-surface"><div class="prov-list-heading"><h3>Listado de proveedores</h3><span>${all.length} registros</span></div><div class="prov-filters"><label class="prov-search-wrap"><span aria-hidden="true">⌕</span><input id="provSearch" type="search" placeholder="Buscar proveedor, razón social, CUIT, localidad, teléfono o email..." value="${esc(query)}" autocomplete="off"></label><label>Estado<select id="provFilterEstado">${options(['Activo','Inactivo'],filterEstado,'Todos')}</select></label><label>Provincia<select id="provFilterProvincia">${options(provinces,filterProvincia,'Todas')}</select></label><label>Rubro<select id="provFilterRubro">${options(rubros,filterRubro,'Todos')}</select></label><button class="prov-filter-icon" type="button" title="Filtros" aria-label="Filtros">☰</button><button class="prov-clear" type="button" data-prov-action="clear">↻ &nbsp; Limpiar</button></div><div class="prov-table-scroll"><table class="prov-table prov-list-table"><thead><tr>${heads.map(([k,l])=>`<th><button type="button" data-prov-sort="${k}">${l}<span>${sortKey===k?(sortDir===1?'↑':'↓'):'↕'}</span></button></th>`).join('')}<th>Acciones</th></tr></thead><tbody>${visible.map(x=>`<tr><td><div class="prov-supplier-name"><span class="prov-avatar">${esc((x.nombre||'?').trim().split(/\s+/).slice(0,2).map(t=>t[0]).join('').toUpperCase())}</span><strong title="${esc(x.nombre)}">${esc(x.nombre)}</strong></div></td><td title="${esc(x.razon)}">${esc(x.razon)||'—'}</td><td>${esc(x.cuit)||'—'}</td><td>${esc(x.localidad)||'—'}</td><td>${esc(x.provincia)||'—'}</td><td><span class="prov-rubro">${esc(x.categoria)||'—'}</span></td><td>${esc(x.telefono)||'—'}</td><td title="${esc(x.email)}">${esc(x.email)||'—'}</td><td><span class="prov-status ${(x.estado||'Activo')==='Inactivo'?'inactive':''}">● &nbsp;${esc(x.estado||'Activo')}</span></td><td><div class="prov-actions"><button type="button" data-prov-detail="${esc(x.id)}" title="Ver ficha" aria-label="Ver ${esc(x.nombre)}">◎</button><button type="button" data-prov-edit="${esc(x.id)}" title="Editar" aria-label="Editar ${esc(x.nombre)}">✎</button><button type="button" class="danger" data-prov-delete="${esc(x.id)}" title="Eliminar" aria-label="Eliminar ${esc(x.nombre)}">♜</button></div></td></tr>`).join('')||'<tr><td colspan="10" class="prov-empty">No se encontraron proveedores con los filtros seleccionados.</td></tr>'}</tbody></table></div><div class="prov-pagination"><div>Mostrar <select id="provPageSize">${[10,20,50,100].map(n=>`<option value="${n}" ${pageSize===n?'selected':''}>${n}</option>`).join('')}</select> de ${filtered.length} registros</div><div class="prov-page-buttons"><button data-prov-page="1" ${page===1?'disabled':''}>«</button><button data-prov-page="${page-1}" ${page===1?'disabled':''}>‹</button>${Array.from({length:Math.min(5,totalPages)},(_,i)=>Math.max(1,Math.min(totalPages-4,page-2))+i).filter(n=>n<=totalPages).map(n=>`<button class="${page===n?'selected':''}" data-prov-page="${n}">${n}</button>`).join('')}${totalPages>5?`<span>… ${totalPages}</span>`:''}<button data-prov-page="${page+1}" ${page===totalPages?'disabled':''}>›</button><button data-prov-page="${totalPages}" ${page===totalPages?'disabled':''}>»</button></div></div></div>${detailId?detail():''}`}

function orderScreen(){const a=orders(),q=orderQuery.toLocaleLowerCase('es');const filtered=a.filter(o=>(orderArrival==='llegaron'?o.estado==='Recibido':o.estado!=='Recibido')&&(!orderStatus||o.estado===orderStatus)&&(!orderSupplier||o.proveedorId===orderSupplier)&&(!orderDateFrom||o.fecha>=orderDateFrom)&&(!orderDateTo||o.fecha<=orderDateTo)&&(!q||[o.numero,o.proveedorNombre,o.fecha,o.entrega,o.estado,o.notas,o.items,o.referencia].join(' ').toLocaleLowerCase('es').includes(q))).sort((x,y)=>(y.fecha||'').localeCompare(x.fecha||'')||String(y.numero).localeCompare(String(x.numero)));const total=Math.max(1,Math.ceil(filtered.length/orderPageSize));orderPage=Math.min(orderPage,total);const pageItems=filtered.slice((orderPage-1)*orderPageSize,orderPage*orderPageSize);const suppliers=data().filter(p=>a.some(o=>o.proveedorId===p.id)).sort((x,y)=>x.nombre.localeCompare(y.nombre,'es'));const fmt=d=>{if(!d)return '—';const m=String(d).match(/^(\d{4})-(\d{2})-(\d{2})$/);return m?`${m[3]}/${m[2]}/${m[1]}`:esc(d)};const stat=[['pink',a.filter(o=>String(o.fecha||'').slice(0,7)===[new Date().getFullYear(),String(new Date().getMonth()+1).padStart(2,'0')].join('-')).length,'Pedidos del mes','cart'],['orange',a.filter(o=>o.estado==='Pendiente').length,'Pedidos pendientes','clock'],['blue',a.filter(o=>o.estado==='Enviado').length,'En camino','truck'],['green',a.filter(o=>o.estado==='Recibido').length,'Recibidos','check']];const icons={cart:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/><path d="M1 1h4l2.7 13.4a2 2 0 0 0 2 1.6h9.7a2 2 0 0 0 2-1.6L23 6H6"/></svg>',clock:'<svg viewBox="0 0 24 24" fill="currentColor"><circle cx="12" cy="12" r="10"/><path d="M12 5v7l5 3" fill="none" stroke="white" stroke-width="1.8" stroke-linecap="round"/></svg>',truck:'<svg viewBox="0 0 24 24" fill="currentColor"><path d="M1 4h13v13H1zM14 8h4l4 5v4h-8z"/><circle cx="6" cy="18" r="2.5"/><circle cx="18" cy="18" r="2.5"/></svg>',check:'<svg viewBox="0 0 24 24" fill="currentColor"><circle cx="12" cy="12" r="10"/><path d="m7 12 3.5 3.5L17 8" fill="none" stroke="white" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>'};return `<div class="prov-list-kpis prov-order-kpis">${stat.map(([c,n,l,i])=>`<div class="prov-list-kpi ${c}"><span class="prov-list-kpi-icon">${icons[i]}</span><span class="prov-list-kpi-copy"><strong>${n}</strong><small>${l}</small></span><span class="prov-list-kpi-arrow" aria-hidden="true">›</span></div>`).join('')}</div><div class="prov-surface prov-list-surface prov-orders-surface"><div class="prov-list-heading"><h3>Listado de pedidos</h3><span>${filtered.length} pedidos</span></div><div class="prov-arrival-tabs" role="group" aria-label="Tipo de pedidos"><button type="button" data-order-arrival="realizados" class="${orderArrival==='realizados'?'active':''}">Pedidos realizados</button><button type="button" data-order-arrival="llegaron" class="${orderArrival==='llegaron'?'active':''}">Pedidos que ya llegaron</button></div><div class="prov-order-filters"><label class="prov-search-wrap prov-order-search"><span aria-hidden="true"><svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.5"/><path d="m16 16 5 5"/></svg></span><input id="provOrderSearch" placeholder="Buscar por número de pedido, proveedor, producto o nota..." value="${esc(orderQuery)}"></label><label>Estado<select id="provOrderStatus"><option value="">Todos</option>${['Pendiente','Enviado','Recibido','Cancelado'].map(x=>`<option ${orderStatus===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Proveedor<select id="provOrderSupplier"><option value="">Todos</option>${suppliers.map(x=>`<option value="${esc(x.id)}" ${orderSupplier===x.id?'selected':''}>${esc(x.nombre)}</option>`).join('')}</select></label><label>Fecha<div class="prov-order-dates"><input type="date" id="provOrderFrom" title="Desde" aria-label="Desde" value="${esc(orderDateFrom)}"><span>–</span><input type="date" id="provOrderTo" title="Hasta" aria-label="Hasta" value="${esc(orderDateTo)}"></div></label><button class="prov-order-filter-icon" title="Filtros" aria-label="Filtros">☷</button><button class="prov-clear" data-prov-action="order-clear">↻ Limpiar</button></div><div class="prov-table-scroll"><table class="prov-table prov-list-table prov-orders-table"><thead><tr>${['N.º Pedido','Fecha','Proveedor','Total','Estado','Entrega estimada','Notas','Acciones'].map(h=>`<th>${h} <span class="prov-sort-glyph">↕</span></th>`).join('')}</tr></thead><tbody>${pageItems.map(o=>`<tr><td><span class="prov-order-number">${esc(o.numero)}</span></td><td>${fmt(o.fecha)}</td><td title="${esc(o.proveedorNombre)}">${esc(o.proveedorNombre)}</td><td>${o.importe?('$ '+Number(o.importe).toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2})):'—'}</td><td><span class="prov-order-status ${esc(o.estado.toLowerCase())}"><span class="prov-order-dot"></span>${o.estado==='Enviado'?'En camino':esc(o.estado)}</span></td><td>${fmt(o.entrega)}</td><td title="${esc(o.notas)}">${esc(o.notas)||'—'}</td><td><div class="prov-actions"><button data-order-detail="${esc(o.id)}" title="Ver pedido" aria-label="Ver pedido">◎</button><button data-order-edit="${esc(o.id)}" title="Editar pedido" aria-label="Editar pedido">✎</button><button data-order-received="${esc(o.id)}" title="${o.estado==='Recibido'?'Volver a pedidos realizados':'Marcar pedido como recibido'}" aria-label="${o.estado==='Recibido'?'Volver a pedidos realizados':'Marcar pedido como recibido'}">${o.estado==='Recibido'?'↶':'✓'}</button><button class="danger" data-order-delete="${esc(o.id)}" title="Eliminar pedido" aria-label="Eliminar pedido"><svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 7h16M10 4h4M6.5 7l.8 13h9.4l.8-13M10 11v6M14 11v6"/></svg></button></div></td></tr>`).join('')||'<tr><td colspan="8" class="prov-empty">Todavía no hay pedidos con estos filtros. Usá «Nuevo pedido» para registrar el primero.</td></tr>'}</tbody></table></div><div class="prov-pagination prov-orders-pagination"><div>Mostrar <select id="provOrderPageSize">${[10,20,50].map(n=>`<option value="${n}" ${orderPageSize===n?'selected':''}>${n}</option>`).join('')}</select> de ${filtered.length} pedidos</div><div class="prov-page-buttons"><button data-order-page="1" ${orderPage===1?'disabled':''}>«</button><button data-order-page="${orderPage-1}" ${orderPage===1?'disabled':''}>‹</button>${Array.from({length:total},(_,i)=>i+1).filter(n=>total<=7||n===1||n===total||Math.abs(n-orderPage)<=2).map((n,i,arr)=>`${i&&n>arr[i-1]+1?'<span class="prov-page-ellipsis">…</span>':''}<button class="${n===orderPage?'selected':''}" data-order-page="${n}">${n}</button>`).join('')}<button data-order-page="${orderPage+1}" ${orderPage===total?'disabled':''}>›</button><button data-order-page="${total}" ${orderPage===total?'disabled':''}>»</button></div></div></div>${orderDetail?orderModal():''}${orderEdit!==null?orderForm():''}`}
const CRONO_KEY='autoservicio_cronograma_semanal_v1';
const scheduleEntries=()=>{try{const a=JSON.parse(localStorage.getItem(CRONO_KEY));return Array.isArray(a)?a:[]}catch{return []}};
const dateISO=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const nextWeekday=(weekday,after)=>{const d=new Date(after.getFullYear(),after.getMonth(),after.getDate(),12);const delta=(Number(weekday)-(d.getDay()+6)%7+7)%7;d.setDate(d.getDate()+delta);return d};
function orderSchedule(providerId,reference){const all=scheduleEntries().filter(x=>x.providerId===providerId);const pickups=all.filter(x=>x.type==='pickup');const deliveries=all.filter(x=>x.type==='delivery');const base=reference?new Date(reference+'T12:00:00'):new Date();if(!Number.isFinite(base.getTime()))return null;const matches=[];for(const pick of pickups){const arrival=deliveries.filter(x=>x.responsable===pick.responsable);if(!arrival.length)continue;const pickupDate=nextWeekday(pick.weekday,base);for(const drop of arrival){let deliveryDate=nextWeekday(drop.weekday,pickupDate);if(deliveryDate<pickupDate)deliveryDate.setDate(deliveryDate.getDate()+7);matches.push({pickup:dateISO(pickupDate),delivery:dateISO(deliveryDate),responsable:pick.responsable})}}matches.sort((a,b)=>a.pickup.localeCompare(b.pickup)||a.delivery.localeCompare(b.delivery));return matches[0]||null}
function updateOrderAuto(form,{preserveDelivery=false}={}){const id=form.elements.proveedorId?.value;const date=form.elements.fecha?.value||dateISO(new Date());const found=id?orderSchedule(id,date):null;const output=form.querySelector('[data-order-auto]');if(output)output.textContent=!id?'Seleccioná un proveedor para calcular la entrega.':found?`Cronograma habitual: pedido ${found.pickup.split('-').reverse().join('/')} · entrega ${found.delivery.split('-').reverse().join('/')} · responsable: ${found.responsable}. Podés modificar ambas fechas sin cambiar el cronograma.`:'No hay fechas configuradas para este proveedor. Podés ingresar las fechas manualmente.';if(!preserveDelivery&&form.elements.entrega)form.elements.entrega.value=found?.delivery||'';if(form.elements.cronoResponsable)form.elements.cronoResponsable.value=found?.responsable||'';if(form.elements.cronoPedidoFecha)form.elements.cronoPedidoFecha.value=found?.pickup||''}
