ent.createElement('div');wrap.className='prov-custom-select';sel.parentNode.insertBefore(wrap,sel);wrap.appendChild(sel);sel.classList.add('prov-native-select');sel.tabIndex=-1;const trigger=document.createElement('button');trigger.type='button';trigger.className='prov-select-trigger';trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');const label=document.createElement('span');label.className='prov-select-label';label.textContent=sel.selectedOptions[0]?.textContent||'Seleccionar';trigger.appendChild(label);trigger.insertAdjacentHTML('beforeend','<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="m6 9 6 6 6-6"/></svg>');const menu=document.createElement('div');menu.className='prov-select-menu';menu.setAttribute('role','listbox');sel.querySelectorAll('option').forEach((opt,i)=>{const item=document.createElement('button');item.type='button';item.className='prov-select-option'+(opt.selected?' is-selected':'');item.textContent=opt.textContent;item.setAttribute('role','option');item.setAttribute('aria-selected',String(opt.selected));item.disabled=opt.disabled;item.addEventListener('click',()=>{sel.selectedIndex=i;sel.dispatchEvent(new Event('change',{bubbles:true}));closeAllSelects();trigger.focus()});menu.appendChild(item)});// Mantener sincronizada la etiqueta visual con el valor real del formulario.
