  document.addEventListener('keydown',onKey);
  overlay.addEventListener('click',e=>{if(e.target===overlay||e.target.closest('[data-delete-cancel]')){close();return}if(e.target.closest('[data-delete-accept]')){saveOrders(orders().filter(o=>String(o.id)!==String(id)));close();render()}});
